html,n=re.subn(r'<section class="student-hero">.*?</section>',hero,html,count=1,flags=re.S)
if n!=1:
    raise SystemExit(f'Không tìm thấy giao diện hồ sơ cũ: {n}')
html=re.sub(r'href="/student\.css(?:\?[^\"]*)?"','href="/student.css?v=20260909-hero-v3"',html,count=1)
